-- GENERATED by tools/build.py. Do not edit.
-- Source of truth is queries/*.sql; edit there and rebuild.
-- Columns, in order: kind, id, ver, loc, extra, perms
--
-- PLATFORM: linux. Run this only on linux. The tables named here do not all
-- exist elsewhere, and osqueryi given a missing table returns "[\n\n]" -- valid,
-- empty, entirely plausible JSON -- and exits 1. Every other artifact in dist/ is for a
-- different platform and is NOT a superset of this one. bin/discover picks by `uname -s`.

-- from browser.sql
SELECT 'ext' AS kind, identifier AS id, version AS ver, profile_path AS loc,
       browser_type AS extra,
       permissions || CASE WHEN manifest_json LIKE '%<all_urls>%' THEN ',<all_urls>' ELSE '' END
         AS perms
  FROM users CROSS JOIN chrome_extensions USING (uid)

UNION ALL

-- from desktop-linux.sql
SELECT 'desktop' AS kind, filename AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/usr/share/applications/%.desktop'
     OR path LIKE '/usr/local/share/applications/%.desktop'
UNION ALL
-- Per-user entries, which is where an AppImage integrated by the user lands rather than
-- anywhere system-wide. /root again gets its own pattern -- see filesystem-linux.sql.
SELECT 'desktop', filename, '', path, '', '' FROM file
  WHERE path LIKE '/home/%/.local/share/applications/%.desktop'
     OR path LIKE '/root/.local/share/applications/%.desktop'

UNION ALL

-- from filesystem-linux.sql
SELECT 'file' AS kind, path AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/home/%/.local/bin/%'
     OR path LIKE '/root/.local/bin/%'
UNION ALL
-- STATE DIRECTORIES, the most install-route-independent signal available: a distro
-- package, an npm global, `curl install.sh | bash` and a source checkout all converge on
-- the same dotdir the first time the agent runs. Package-manager branches see only the
-- route that was used, and see nothing at all for a source build.
--
-- THE TRAILING SLASH IS LOAD-BEARING, on Linux exactly as on macOS. osquery translates
-- LIKE into its glob engine, where a directory must be addressed with a trailing slash:
--     path LIKE '/home/%/.claude'   -> 0 rows, no error
--     path LIKE '/home/%/.claude/'  -> the directory
-- Do not "tidy" the slash away.
--
-- `.` AND `..` COME BACK FROM THIS GLOB SHAPE and are excluded structurally. Measured in
-- an Ubuntu container and then confirmed on a reference Mac, where 4 of the 47 dotdir
-- rows were /Users/x/./ and /Users/x/../ -- so this is a pre-existing wart found on Linux
-- and fixed in both files, not a Linux quirk. They are payload that can never match and
-- they arrive as unmatched rows a reader has to dismiss by hand.
SELECT 'file', path, '', path, '', '' FROM file
  WHERE (path LIKE '/home/%/.%/' OR path LIKE '/root/.%/')
    AND path NOT LIKE '%/./'
    AND path NOT LIKE '%/../'
UNION ALL
-- PYTHON-PACKAGED AGENTS. python_packages is deliberately absent here for the same
-- reason it is absent on macOS -- 15.6s with no WHERE push-down -- so glob the INSTALL
-- LOCATIONS instead. pipx and uv each give a tool its own directory named for the
-- package, which is precise, bounded and free, and bin/classify's TOOL_DIR bridge is
-- what turns that path back into a package name.
SELECT 'file', path, '', path, '', '' FROM file
  WHERE path LIKE '/home/%/.local/pipx/venvs/%/'
     OR path LIKE '/home/%/.local/share/uv/tools/%/'
     OR path LIKE '/root/.local/pipx/venvs/%/'
     OR path LIKE '/root/.local/share/uv/tools/%/'
-- KNOWN GAP, deliberately not covered, and the same one macOS has: packages executed via
-- `npx`/`bunx` and never installed land in a content-addressed cache where the invoked
-- package is indistinguishable BY PATH from its transitive dependencies.

UNION ALL

-- from native-messaging-linux.sql
SELECT 'nmh' AS kind, filename AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/home/%/.config/%/NativeMessagingHosts/%.json'
     OR path LIKE '/root/.config/%/NativeMessagingHosts/%.json'
UNION ALL
-- Firefox uses a lower-case directory in the user scope as well, and it is not under
-- .config at all.
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/home/%/.mozilla/native-messaging-hosts/%.json'
     OR path LIKE '/root/.mozilla/native-messaging-hosts/%.json'
UNION ALL
-- The system scope: /etc/opt/chrome/... for Chrome, /etc/chromium/... for Chromium, and
-- /usr/lib/mozilla/... for Firefox. Two patterns because the depth differs by one.
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/etc/%/native-messaging-hosts/%.json'
     OR path LIKE '/etc/opt/%/native-messaging-hosts/%.json'
     OR path LIKE '/usr/lib/%/native-messaging-hosts/%.json'

UNION ALL

-- from packages-linux.sql
SELECT 'deb' AS kind, name AS id, version AS ver, '' AS loc, arch AS extra, '' AS perms
  FROM deb_packages
  WHERE status LIKE '%ok installed'
UNION ALL
-- rpm_packages has no status column and needs no equivalent filter: the rpm database
-- holds installed packages only, with no remove-but-retain state to confuse.
--
-- `vendor` ships in `extra`, and it is the ONLY route on any platform that hands us a
-- vendor string from the artifact itself -- 'Fedora Project' for the distro's own
-- packages, the publisher's name for a third party. Everywhere else vendor has to be
-- inferred from an identifier, which is how `com.todesktop.230313mzl4w4u92` reads as a
-- ToDesktop product rather than a Cursor one.
SELECT 'rpm', name, version, '', vendor, '' FROM rpm_packages

UNION ALL

-- from packages.sql
SELECT 'npm' AS kind, name AS id, version AS ver, path AS loc, '' AS extra, '' AS perms
  FROM npm_packages
  WHERE path NOT LIKE '%/node_modules/%/node_modules/%'

UNION ALL

-- from ports.sql
SELECT 'port' AS kind, CAST(lp.port AS TEXT) AS id, '' AS ver, p.path AS loc,
       lp.address AS extra, '' AS perms
  FROM listening_ports lp JOIN processes p USING (pid)
  WHERE lp.port > 0

UNION ALL

-- from runtime-linux.sql
SELECT 'unit' AS kind, id AS id, '' AS ver, fragment_path AS loc,
       unit_file_state AS extra, '' AS perms
  FROM systemd_units
UNION ALL
-- THE MARKER, in the vocabulary bin/classify already understands: `ok` is provenance and
-- anything else becomes a gap the reader is told about rather than a silence.
--
-- SOCKET PRESENCE ALONE IS NOT ENOUGH, and finding that out is what shaped this. Checking
-- only for the bus socket reports `ok` against a socket that exists but has nothing
-- serving it -- reproduced by binding one and watching systemd_units still fail with
-- `Connection refused ... NoServer`. That is precisely the Docker `wedge` state this repo
-- already documents: a health check is necessary and not sufficient.
--
-- So the marker reasons from the UNIT COUNT first, which is the only evidence that
-- actually proves the bus was read:
--
--     units > 0            -> ok         we read the list, so the rows above are real
--     no bus socket        -> absent     nothing to read from, and we know why
--     socket, but 0 units  -> unhealthy  the socket is there and the list came back
--                                        empty, which no real systemd host does
--
-- A host with systemd genuinely has hundreds of units, so zero-with-a-socket is a failure
-- and never a clean machine. Computed entirely in SQL: no runner change, and it travels
-- with a cached payload the same way the container marker does.
--
-- THE SUBQUERIES ARE IN THE FROM CLAUSE, NOT THE COLUMN LIST, and that is deliberate:
-- test/lint.sh reads a branch's columns as the text between SELECT and the first FROM, so
-- a subquery in the column list would truncate the count and the contract check would
-- pass a five-column arm.
SELECT 'scan' AS kind, 'systemd' AS id, CAST(t.unix_time AS TEXT) AS ver,
       '/run/dbus/system_bus_socket' AS loc,
       CASE WHEN u.n > 0 THEN 'ok'
            WHEN s.n = 0 THEN 'absent'
            ELSE 'unhealthy:no-units' END AS extra,
       '' AS perms
  FROM time t,
       (SELECT COUNT(*) AS n FROM systemd_units) u,
       (SELECT COUNT(*) AS n FROM file
          WHERE path = '/run/dbus/system_bus_socket') s

UNION ALL

-- from vscode.sql
SELECT 'vscodeext' AS kind, name AS id, version AS ver, path AS loc,
       vscode_edition AS extra, '' AS perms
  FROM users CROSS JOIN vscode_extensions USING (uid);
